{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@troed/oc-ctx-handover",
  "version": "0.1.0",
  "description": "OpenCode plugin that hands a session over to a fresh context through a deliberate HANDOVER.md document instead of automatic compaction.",
  "type": "module",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "src"
  ],
  "scripts": {
    "test": "node --test",
    "prepack": "npm test"
  },
  "publishConfig": {
    "access": "public"
  },
  "license": "CC0-1.0",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context",
    "compaction",
    "handover"
  ]
}
